using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.RunModifiers;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "StartPlayerTurnState", menuName = "Data/Battle/Game States/Start Player Turn State")]
public class StartPlayerTurnState : GameState
{
	[Header("Player Runes")]
	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[Header("Enemies")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnUpdatePlayerCorruption;

	[Header("Components")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[NonSerialized]
	private List<IEnumerator> startTurnActivations = new List<IEnumerator>();

	[NonSerialized]
	private bool init;

	public List<IEnumerator> StartTurnActivations => startTurnActivations;

	public void OnReset()
	{
		startTurnActivations.Clear();
		init = false;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		CoroutineHandler instance = ReferenceSingleton<CoroutineHandler>.Instance;
		if (!init)
		{
			instance.Run(StartPlayerTurn());
			return;
		}
		if (startTurnActivations.Count > 0)
		{
			ActivateNextStartTurnActivation();
			return;
		}
		"No more activations".DebugLogIfVerbose(verbose);
		instance.Run(DrawDiceFromStartOfTurn());
	}

	private void ActivateNextStartTurnActivation()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		"Activating Next Start Turn Activation".DebugLogIfVerbose(verbose);
		("StartTurnActivations: " + startTurnActivations.Count).DebugLogIfVerbose(verbose);
		instance.ActionsQueueState.EnqueueAction(startTurnActivations.PopFirst(), ignoreNextRunActionWaitForFramesOnMobile: true);
		instance.SetState(instance.ActionsQueueState);
	}

	private IEnumerator StartPlayerTurn()
	{
		Debug.Log("============================== PLAYER TURN ==================================");
		startTurnActivations.Clear();
		init = true;
		if (!playerCurrentRunes.PlayerHaveFallenStar)
		{
			playerCurrentRunes.usedRuneIndexes.Clear();
		}
		yield return new WaitForSeconds(0.15f);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartOmensStartOfPlayerTurn();
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RestartEffectsPerTurnCounters();
		startTurnActivations.Add(ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.ActivateBrightResonatorOmenAction());
		startTurnActivations.Add(ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.ActivateStartOfTurneforeLightShieldRemovalOmenActions());
		startTurnActivations.Add(OnBeforeBeforeDrawDicePhaseEffects());
		startTurnActivations.Add(OnBeforeDrawDicePhaseEffects());
		startTurnActivations.Add(ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.ActivateStartOfTurnOmenActions());
		startTurnActivations.Add(ReferenceSingleton<RunModifiersManager>.Instance.ActivateStartOfTurnRunModifierActions());
		startTurnActivations.Add(PlayerAndCompanionsStartTurnActivation());
		ActivateNextStartTurnActivation();
	}

	private IEnumerator OnBeforeBeforeDrawDicePhaseEffects()
	{
		bool flag = false;
		if (playerGameObjectReference.value.GetComponent<UnitEffects>().OnBeforeBeforeDrawDicePhaseEffect())
		{
			flag = true;
		}
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			if (currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>().OnBeforeBeforeDrawDicePhaseEffect())
			{
				flag = true;
			}
		}
		for (int j = 0; j < currentCorruptedAnimals.activeCorruptedAnimals.Count; j++)
		{
			if (currentCorruptedAnimals.activeCorruptedAnimals[j].GetComponent<CorruptedAnimalEffects>().OnBeforeBeforeDrawDicePhaseEffect())
			{
				flag = true;
			}
		}
		if (flag)
		{
			yield return new WaitForSeconds(0.3f);
		}
	}

	private IEnumerator OnBeforeDrawDicePhaseEffects()
	{
		bool flag = false;
		if (playerGameObjectReference.value.GetComponent<UnitEffects>().OnBeforeDrawDicePhaseEffects())
		{
			flag = true;
		}
		Debug.Log("-------------OnBeforeDrawDicePhaseEffects currentCompanions.currentCompanions.RuntimeCompanions.Count: " + currentCompanions.RuntimeCompanions.Count);
		Debug.Log("-------------OnBeforeDrawDicePhaseEffects currentCompanions.ActiveCompanions.Count: " + currentCompanions.ActiveCompanions.Count);
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			if (currentCompanions.ActiveCompanions[i] == null)
			{
				Debug.Log("-------------OnBeforeDrawDicePhaseEffects currentCompanions.ActiveCompanions[i] IS NULL-------------");
			}
			UnitEffects component = currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>();
			if (component == null)
			{
				Debug.Log("-------------OnBeforeDrawDicePhaseEffects currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>() IS NULL-------------");
			}
			if (component.OnBeforeDrawDicePhaseEffects())
			{
				flag = true;
			}
		}
		for (int j = 0; j < currentCorruptedAnimals.activeCorruptedAnimals.Count; j++)
		{
			if (currentCorruptedAnimals.activeCorruptedAnimals[j].GetComponent<CorruptedAnimalEffects>().OnBeforeDrawDicePhaseEffects())
			{
				flag = true;
			}
		}
		if (flag)
		{
			yield return new WaitForSeconds(0.3f);
		}
		float num = 0f;
		if (!ReferenceSingleton<RunModifiersManager>.Instance.MalfunctioningSentinelsRunModifierActive)
		{
			for (int num2 = currentCompanions.DecayedCompanions.Count - 1; num2 >= 0; num2--)
			{
				CompanionInitializer component2 = currentCompanions.DecayedCompanions[num2].GetComponent<CompanionInitializer>();
				if (component2.CheckSentinelBrokenTurnsCounter())
				{
					num = component2.SentinelAutoRepairHUD.CompanionRepairedAutomaticallyDelayForStartPlayerTurnState;
				}
			}
		}
		if (num > 0f)
		{
			yield return new WaitForSeconds(num);
		}
	}

	private IEnumerator PlayerAndCompanionsStartTurnActivation()
	{
		UnitEffects component = playerGameObjectReference.value.GetComponent<UnitEffects>();
		bool flag = false;
		if (component.OnStartTurnEffects())
		{
			flag = true;
		}
		Debug.Log("-------------CompanionsStartTurnActivation currentCompanions.currentCompanions.RuntimeCompanions.Count: " + currentCompanions.RuntimeCompanions.Count);
		Debug.Log("-------------CompanionsStartTurnActivation currentCompanions.ActiveCompanions.Count: " + currentCompanions.ActiveCompanions.Count);
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			if (currentCompanions.ActiveCompanions[i] == null)
			{
				Debug.Log("-------------CompanionsStartTurnActivation currentCompanions.ActiveCompanions[i] IS NULL-------------");
			}
			UnitEffects component2 = currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>();
			if (component2 == null)
			{
				Debug.Log("-------------CompanionsStartTurnActivation currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>() IS NULL-------------");
			}
			if (component2.OnStartTurnEffects())
			{
				flag = true;
			}
		}
		if (flag)
		{
			yield return new WaitForSeconds(0.3f);
		}
	}

	private IEnumerator DrawDiceFromStartOfTurn()
	{
		yield return new WaitForSeconds(0.3f);
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ReferenceSingleton<DiceDrawingHandler>.Instance.DrawingDiceCoroutine());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		OnUpdatePlayerCorruption.Raise();
		init = false;
	}
}
